insert into public.question_hints (id,question_id,content_markdown,sort_order) values
('60000000-0000-4000-8000-000093100071','40000000-0000-4000-8000-000000930007','Compare o produto entre a fração de instruções e o CPI antes e depois da otimização.',1),
('60000000-0000-4000-8000-000093100072','40000000-0000-4000-8000-000000930007','A redução de instruções só ajuda se compensar o aumento de CPI.',2),
('60000000-0000-4000-8000-000093100073','40000000-0000-4000-8000-000000930007','Use o tempo inicial como referência igual a 1, sem ainda converter a diferença em porcentagem.',3),
('60000000-0000-4000-8000-000093100131','40000000-0000-4000-8000-000000930013','Separe a fração serial da fração paralelizável.',1),
('60000000-0000-4000-8000-000093100132','40000000-0000-4000-8000-000000930013','No limite de muitos processadores, a parte paralela deixa de dominar a expressão.',2),
('60000000-0000-4000-8000-000093100133','40000000-0000-4000-8000-000000930013','Use apenas a fração serial para estabelecer um teto finito de aceleração.',3),
('60000000-0000-4000-8000-000093100151','40000000-0000-4000-8000-000000930015','Cada combinação das linhas de endereço seleciona uma posição.',1),
('60000000-0000-4000-8000-000093100152','40000000-0000-4000-8000-000000930015','Como o endereçamento é por byte, uma posição corresponde a um byte.',2),
('60000000-0000-4000-8000-000093100153','40000000-0000-4000-8000-000000930015','Converta o total de posições para uma unidade binária apropriada antes de comparar as opções.',3),
('60000000-0000-4000-8000-000093100191','40000000-0000-4000-8000-000000930019','Distingua taxa de hit de taxa de miss.',1),
('60000000-0000-4000-8000-000093100192','40000000-0000-4000-8000-000000930019','A penalidade é paga somente nos acessos que erram a cache.',2),
('60000000-0000-4000-8000-000093100193','40000000-0000-4000-8000-000000930019','Monte tempo de hit mais taxa de miss vezes penalidade, deixando a soma final para você.',3),
('60000000-0000-4000-8000-000093100301','40000000-0000-4000-8000-000000930030','Observe os sinais dos dois operandos em cada soma proposta.',1),
('60000000-0000-4000-8000-000093100302','40000000-0000-4000-8000-000000930030','Overflow em complemento de dois exige dois operandos do mesmo sinal e resultado de sinal oposto.',2),
('60000000-0000-4000-8000-000093100303','40000000-0000-4000-8000-000000930030','Verifique qual soma ultrapassa a faixa de $-128$ a $127$, sem escolher ainda a alternativa.',3),
('60000000-0000-4000-8000-000093100311','40000000-0000-4000-8000-000000930031','Reescreva a subtração como soma de um número positivo com o complemento de dois do outro.',1),
('60000000-0000-4000-8000-000093100312','40000000-0000-4000-8000-000000930031','Converta $27$ para seu oposto em oito bits antes de somar.',2),
('60000000-0000-4000-8000-000093100313','40000000-0000-4000-8000-000000930031','Confira se o padrão final, interpretado com sinal, corresponde a uma diferença negativa.',3),
('60000000-0000-4000-8000-000093100331','40000000-0000-4000-8000-000000930033','Some separadamente os dígitos de menor ordem em base 16.',1),
('60000000-0000-4000-8000-000093100332','40000000-0000-4000-8000-000000930033','Quando a soma de um dígito chega a 16, transporte uma unidade para a coluna seguinte.',2),
('60000000-0000-4000-8000-000093100333','40000000-0000-4000-8000-000000930033','Converta o transporte e os dois dígitos resultantes para hexadecimal antes de marcar a opção.',3),
('60000000-0000-4000-8000-000093100441','40000000-0000-4000-8000-000000930044','Conte os bits $1$ existentes na palavra original.',1),
('60000000-0000-4000-8000-000093100442','40000000-0000-4000-8000-000000930044','Paridade par exige um número total par de bits $1$ após acrescentar o novo bit.',2),
('60000000-0000-4000-8000-000093100443','40000000-0000-4000-8000-000000930044','Decida se o total atual já satisfaz essa condição, sem nomear o bit a inserir.',3),
('60000000-0000-4000-8000-000093100481','40000000-0000-4000-8000-000000930048','Use os pesos fracionários binários $1/2$, $1/4$ e $1/8$.',1),
('60000000-0000-4000-8000-000093100482','40000000-0000-4000-8000-000000930048','Decomponha a fração decimal em uma soma desses pesos.',2),
('60000000-0000-4000-8000-000093100483','40000000-0000-4000-8000-000000930048','Marque os pesos usados na expansão e só então forme a sequência de bits.',3)
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values
('70000000-0000-4000-8000-000093100011','40000000-0000-4000-8000-000000930001','Dados: Trocar a microarquitetura mantendo a mesma ISA.','Um compilador transforma um programa em C em código de máquina para uma ISA específica. Qual mudança pode ocorrer sem exigir que o código-fonte em C seja reescrito?',1),
('70000000-0000-4000-8000-000093100012','40000000-0000-4000-8000-000000930001','Princípio: Trocar a microarquitetura mantendo a mesma ISA.','A ISA é a interface visível ao software de baixo nível; a microarquitetura é uma implementação dessa interface.',2),
('70000000-0000-4000-8000-000093100013','40000000-0000-4000-8000-000000930001','Estratégia: Trocar a microarquitetura mantendo a mesma ISA.','Compare o que o compilador assume — a ISA — com a forma interna de executá-la.',3),
('70000000-0000-4000-8000-000093100014','40000000-0000-4000-8000-000000930001','Verificação: Trocar a microarquitetura mantendo a mesma ISA.','Se as instruções preservam significado e efeitos, o binário continua válido.',4),
('70000000-0000-4000-8000-000093100015','40000000-0000-4000-8000-000000930001','Conclusão: Trocar a microarquitetura mantendo a mesma ISA.','A alternativa correta é “Trocar a microarquitetura mantendo a mesma ISA.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100021','40000000-0000-4000-8000-000000930002','Dados: A microarquitetura.','Uma equipe substitui uma ULA de 32 bits por outra mais rápida, sem alterar registradores, opcodes nem resultados das instruções. Que camada foi modificada?',1),
('70000000-0000-4000-8000-000093100022','40000000-0000-4000-8000-000000930002','Princípio: A microarquitetura.','Componentes e caminhos internos pertencem à implementação, desde que a interface arquitetural seja preservada.',2),
('70000000-0000-4000-8000-000093100023','40000000-0000-4000-8000-000000930002','Estratégia: A microarquitetura.','Pergunte se um programador que usa a ISA percebe uma instrução diferente.',3),
('70000000-0000-4000-8000-000093100024','40000000-0000-4000-8000-000000930002','Verificação: A microarquitetura.','Os mesmos registradores, opcodes e resultados indicam compatibilidade arquitetural.',4),
('70000000-0000-4000-8000-000093100025','40000000-0000-4000-8000-000000930002','Conclusão: A microarquitetura.','A alternativa correta é “A microarquitetura.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100031','40000000-0000-4000-8000-000000930003','Dados: A implementação mudou, mas a ISA pode permanecer compatível.','Um processador passa a executar uma multiplicação por meio de várias microoperações internas em vez de uma unidade dedicada, mas a instrução MUL mantém seus operandos e resultado. Qual afirmação é correta?',1),
('70000000-0000-4000-8000-000093100032','40000000-0000-4000-8000-000000930003','Princípio: A implementação mudou, mas a ISA pode permanecer compatível.','Uma mesma instrução arquitetural pode ser realizada por diferentes sequências internas.',2),
('70000000-0000-4000-8000-000093100033','40000000-0000-4000-8000-000000930003','Estratégia: A implementação mudou, mas a ISA pode permanecer compatível.','Diferencie o contrato da instrução de sua realização física ou microprogramada.',3),
('70000000-0000-4000-8000-000093100034','40000000-0000-4000-8000-000000930003','Verificação: A implementação mudou, mas a ISA pode permanecer compatível.','O resultado e os efeitos observáveis de MUL são o teste de compatibilidade.',4),
('70000000-0000-4000-8000-000093100035','40000000-0000-4000-8000-000000930003','Conclusão: A implementação mudou, mas a ISA pode permanecer compatível.','A alternativa correta é “A implementação mudou, mas a ISA pode permanecer compatível.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100041','40000000-0000-4000-8000-000000930004','Dados: Porque ambos podem realizar a mesma transformação lógica, com custos e velocidades diferentes.','Por que uma função como compressão pode ser implementada em hardware ou em software?',1),
('70000000-0000-4000-8000-000093100042','40000000-0000-4000-8000-000000930004','Princípio: Porque ambos podem realizar a mesma transformação lógica, com custos e velocidades diferentes.','A escolha hardware/software é um trade-off de desempenho, custo, consumo e flexibilidade, não uma diferença de capacidade lógica.',2),
('70000000-0000-4000-8000-000093100043','40000000-0000-4000-8000-000000930004','Estratégia: Porque ambos podem realizar a mesma transformação lógica, com custos e velocidades diferentes.','Avalie a transformação desejada e os custos de cada implementação.',3),
('70000000-0000-4000-8000-000093100044','40000000-0000-4000-8000-000000930004','Verificação: Porque ambos podem realizar a mesma transformação lógica, com custos e velocidades diferentes.','Uma solução em hardware pode acelerar uma função sem tornar a alternativa em software impossível.',4),
('70000000-0000-4000-8000-000093100045','40000000-0000-4000-8000-000000930004','Conclusão: Porque ambos podem realizar a mesma transformação lógica, com custos e velocidades diferentes.','A alternativa correta é “Porque ambos podem realizar a mesma transformação lógica, com custos e velocidades diferentes.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100051','40000000-0000-4000-8000-000000930005','Dados: Uma máquina virtual em um nível de abstração superior.','Um interpretador executa bytecodes e oferece instruções que não existem diretamente no processador físico. O conjunto de bytecodes descreve principalmente:',1),
('70000000-0000-4000-8000-000093100052','40000000-0000-4000-8000-000000930005','Princípio: Uma máquina virtual em um nível de abstração superior.','Uma máquina virtual define objetos e operações próprios, mesmo quando precisa ser interpretada por outro nível.',2),
('70000000-0000-4000-8000-000093100053','40000000-0000-4000-8000-000000930005','Estratégia: Uma máquina virtual em um nível de abstração superior.','Identifique qual conjunto de operações é apresentado ao programador daquele ambiente.',3),
('70000000-0000-4000-8000-000093100054','40000000-0000-4000-8000-000000930005','Verificação: Uma máquina virtual em um nível de abstração superior.','O fato de bytecodes serem interpretados não os transforma em sinais elétricos da CPU.',4),
('70000000-0000-4000-8000-000093100055','40000000-0000-4000-8000-000000930005','Conclusão: Uma máquina virtual em um nível de abstração superior.','A alternativa correta é “Uma máquina virtual em um nível de abstração superior.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100061','40000000-0000-4000-8000-000000930006','Dados: B, pois seu tempo proporcional é menor.','Dois processadores executam o mesmo programa. A usa clock de 3 GHz e CPI médio 1,5; B usa 2 GHz e CPI médio 0,8, com o mesmo número de instruções. Qual é mais rápido?',1),
('70000000-0000-4000-8000-000093100062','40000000-0000-4000-8000-000000930006','Princípio: B, pois seu tempo proporcional é menor.','Tempo de CPU é proporcional a instruções × CPI ÷ frequência.',2),
('70000000-0000-4000-8000-000093100063','40000000-0000-4000-8000-000000930006','Estratégia: B, pois seu tempo proporcional é menor.','Compare $1,5/3$ com $0,8/2$, usando a mesma unidade de GHz.',3),
('70000000-0000-4000-8000-000093100064','40000000-0000-4000-8000-000000930006','Verificação: B, pois seu tempo proporcional é menor.','B resulta em $0,4$ contra $0,5$ unidades proporcionais de tempo.',4),
('70000000-0000-4000-8000-000093100065','40000000-0000-4000-8000-000000930006','Conclusão: B, pois seu tempo proporcional é menor.','A alternativa correta é “B, pois seu tempo proporcional é menor.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100071','40000000-0000-4000-8000-000000930007','Dados: O tempo aumenta 4%.','Uma otimização reduz em 20% a contagem de instruções, mas eleva o CPI de 1,0 para 1,3; o clock não muda. Qual efeito ocorre?',1),
('70000000-0000-4000-8000-000093100072','40000000-0000-4000-8000-000000930007','Princípio: O tempo aumenta 4%.','Com clock constante, compare o produto entre número de instruções e CPI antes e depois.',2),
('70000000-0000-4000-8000-000093100073','40000000-0000-4000-8000-000000930007','Estratégia: O tempo aumenta 4%.','Calcule $0,80\times1,30$ para o novo trabalho relativo.',3),
('70000000-0000-4000-8000-000093100074','40000000-0000-4000-8000-000000930007','Verificação: O tempo aumenta 4%.','O produto é $1,04$, maior que o valor inicial $1,00$.',4),
('70000000-0000-4000-8000-000093100075','40000000-0000-4000-8000-000000930007','Conclusão: O tempo aumenta 4%.','A alternativa correta é “O tempo aumenta 4%.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100081','40000000-0000-4000-8000-000000930008','Dados: A ULA.','Qual componente executa operações aritméticas e lógicas sobre operandos que já estão disponíveis no caminho de dados?',1),
('70000000-0000-4000-8000-000093100082','40000000-0000-4000-8000-000000930008','Princípio: A ULA.','A ULA realiza cálculos; PC, IR e barramentos exercem papéis de controle, armazenamento ou comunicação.',2),
('70000000-0000-4000-8000-000093100083','40000000-0000-4000-8000-000000930008','Estratégia: A ULA.','Associe a operação solicitada ao bloco que soma, compara e aplica lógica booleana.',3),
('70000000-0000-4000-8000-000093100084','40000000-0000-4000-8000-000000930008','Verificação: A ULA.','A descrição não pede guardar endereço nem buscar instrução.',4),
('70000000-0000-4000-8000-000093100085','40000000-0000-4000-8000-000000930008','Conclusão: A ULA.','A alternativa correta é “A ULA.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100091','40000000-0000-4000-8000-000000930009','Dados: Carregar o endereço-alvo no PC.','Após buscar uma instrução, a CPU descobre que ela é um salto condicional tomado. Qual atualização é essencial antes da próxima busca?',1),
('70000000-0000-4000-8000-000093100092','40000000-0000-4000-8000-000000930009','Princípio: Carregar o endereço-alvo no PC.','O PC determina o endereço da próxima instrução a buscar.',2),
('70000000-0000-4000-8000-000093100093','40000000-0000-4000-8000-000000930009','Estratégia: Carregar o endereço-alvo no PC.','Siga a consequência do desvio: a próxima instrução não é a sequencial.',3),
('70000000-0000-4000-8000-000093100094','40000000-0000-4000-8000-000000930009','Verificação: Carregar o endereço-alvo no PC.','Sem atualizar o PC, a busca continuaria no caminho incorreto.',4),
('70000000-0000-4000-8000-000093100095','40000000-0000-4000-8000-000000930009','Conclusão: Carregar o endereço-alvo no PC.','A alternativa correta é “Carregar o endereço-alvo no PC.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100101','40000000-0000-4000-8000-000000930010','Dados: Usar R2 como endereço, ler memória e escrever o dado em R1.','Durante a execução de LOAD R1,[R2], qual sequência representa corretamente o uso lógico dos componentes?',1),
('70000000-0000-4000-8000-000093100102','40000000-0000-4000-8000-000000930010','Princípio: Usar R2 como endereço, ler memória e escrever o dado em R1.','Uma carga transfere para um registrador o conteúdo da posição apontada pelo operando de endereço.',2),
('70000000-0000-4000-8000-000093100103','40000000-0000-4000-8000-000000930010','Estratégia: Usar R2 como endereço, ler memória e escrever o dado em R1.','Separe registrador-base, endereço efetivo, leitura de memória e destino.',3),
('70000000-0000-4000-8000-000093100104','40000000-0000-4000-8000-000000930010','Verificação: Usar R2 como endereço, ler memória e escrever o dado em R1.','O valor armazenado em R2 é endereço; o dado lido torna-se o novo valor de R1.',4),
('70000000-0000-4000-8000-000093100105','40000000-0000-4000-8000-000000930010','Conclusão: Usar R2 como endereço, ler memória e escrever o dado em R1.','A alternativa correta é “Usar R2 como endereço, ler memória e escrever o dado em R1.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100111','40000000-0000-4000-8000-000000930011','Dados: Instruções simples e formatos regulares.','Qual característica é mais associada a uma ISA RISC clássica?',1),
('70000000-0000-4000-8000-000093100112','40000000-0000-4000-8000-000000930011','Princípio: Instruções simples e formatos regulares.','RISC favorece regularidade e operações simples, o que ajuda decodificação e pipeline.',2),
('70000000-0000-4000-8000-000093100113','40000000-0000-4000-8000-000000930011','Estratégia: Instruções simples e formatos regulares.','Procure a alternativa que descreve o conjunto de instruções, não a memória física.',3),
('70000000-0000-4000-8000-000093100114','40000000-0000-4000-8000-000000930011','Verificação: Instruções simples e formatos regulares.','Registradores continuam centrais em arquiteturas RISC.',4),
('70000000-0000-4000-8000-000093100115','40000000-0000-4000-8000-000000930011','Conclusão: Instruções simples e formatos regulares.','A alternativa correta é “Instruções simples e formatos regulares.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100121','40000000-0000-4000-8000-000000930012','Dados: Paralelismo no nível do processador.','Quatro núcleos executam quatro tarefas independentes, cada uma com duração semelhante. Qual ganho é mais diretamente explorado?',1),
('70000000-0000-4000-8000-000093100122','40000000-0000-4000-8000-000000930012','Princípio: Paralelismo no nível do processador.','Múltiplos núcleos permitem executar fluxos independentes simultaneamente.',2),
('70000000-0000-4000-8000-000093100123','40000000-0000-4000-8000-000000930012','Estratégia: Paralelismo no nível do processador.','Verifique se o paralelismo vem de várias tarefas ou da sobreposição de etapas de uma só CPU.',3),
('70000000-0000-4000-8000-000093100124','40000000-0000-4000-8000-000000930012','Verificação: Paralelismo no nível do processador.','As tarefas distintas podem ser distribuídas entre núcleos sem criar dependências entre si.',4),
('70000000-0000-4000-8000-000093100125','40000000-0000-4000-8000-000000930012','Conclusão: Paralelismo no nível do processador.','A alternativa correta é “Paralelismo no nível do processador.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100131','40000000-0000-4000-8000-000000930013','Dados: $5$.','Um programa possui 80% de seu tempo perfeitamente paralelizável e 20% inevitavelmente serial. Pelo limite de Amdahl, qual é o ganho máximo com infinitos processadores?',1),
('70000000-0000-4000-8000-000093100132','40000000-0000-4000-8000-000000930013','Princípio: $5$.','A parte serial limita o ganho global: speedup máximo é $1/f_{serial}$.',2),
('70000000-0000-4000-8000-000093100133','40000000-0000-4000-8000-000000930013','Estratégia: $5$.','Faça o número de processadores tender ao infinito na expressão de Amdahl.',3),
('70000000-0000-4000-8000-000093100134','40000000-0000-4000-8000-000000930013','Verificação: $5$.','Com fração serial $0,20$, o limite é $1/0,20=5$.',4),
('70000000-0000-4000-8000-000093100135','40000000-0000-4000-8000-000000930013','Conclusão: $5$.','A alternativa correta é “$5$.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100141','40000000-0000-4000-8000-000000930014','Dados: Selecionar a posição cujo conteúdo será lido ou escrito.','Qual é a função primária de um endereço de memória?',1),
('70000000-0000-4000-8000-000093100142','40000000-0000-4000-8000-000000930014','Princípio: Selecionar a posição cujo conteúdo será lido ou escrito.','Endereço identifica uma localização; dado é o conteúdo transferido dessa localização.',2),
('70000000-0000-4000-8000-000093100143','40000000-0000-4000-8000-000000930014','Estratégia: Selecionar a posição cujo conteúdo será lido ou escrito.','Diferencie “onde” está a informação de “qual” é a informação.',3),
('70000000-0000-4000-8000-000093100144','40000000-0000-4000-8000-000000930014','Verificação: Selecionar a posição cujo conteúdo será lido ou escrito.','Um mesmo endereço pode conter valores diferentes ao longo do tempo.',4),
('70000000-0000-4000-8000-000093100145','40000000-0000-4000-8000-000000930014','Conclusão: Selecionar a posição cujo conteúdo será lido ou escrito.','A alternativa correta é “Selecionar a posição cujo conteúdo será lido ou escrito.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100151','40000000-0000-4000-8000-000000930015','Dados: $64$ KiB.','Uma memória é endereçável por byte e possui 16 linhas de endereço. Qual capacidade diretamente endereçável ela tem?',1),
('70000000-0000-4000-8000-000093100152','40000000-0000-4000-8000-000000930015','Princípio: $64$ KiB.','Com $n$ linhas de endereço existem $2^n$ posições; cada posição contém um byte.',2),
('70000000-0000-4000-8000-000093100153','40000000-0000-4000-8000-000000930015','Estratégia: $64$ KiB.','Calcule $2^{16}$ e converta bytes para KiB.',3),
('70000000-0000-4000-8000-000093100154','40000000-0000-4000-8000-000000930015','Verificação: $64$ KiB.','$2^{16}=65536$ bytes, isto é, $64$ KiB.',4),
('70000000-0000-4000-8000-000093100155','40000000-0000-4000-8000-000000930015','Conclusão: $64$ KiB.','A alternativa correta é “$64$ KiB.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100161','40000000-0000-4000-8000-000000930016','Dados: $0x78$.','Uma palavra de 32 bits $0x12345678$ é armazenada no endereço 100 em máquina little-endian. Qual byte fica no endereço 100?',1),
('70000000-0000-4000-8000-000093100162','40000000-0000-4000-8000-000000930016','Princípio: $0x78$.','Little-endian coloca o byte menos significativo no menor endereço.',2),
('70000000-0000-4000-8000-000093100163','40000000-0000-4000-8000-000000930016','Estratégia: $0x78$.','Separe a palavra em $12$, $34$, $56$ e $78$ e ordene os endereços crescentes.',3),
('70000000-0000-4000-8000-000093100164','40000000-0000-4000-8000-000000930016','Verificação: $0x78$.','O menor endereço recebe o byte menos significativo.',4),
('70000000-0000-4000-8000-000093100165','40000000-0000-4000-8000-000000930016','Conclusão: $0x78$.','A alternativa correta é “$0x78$.”, pois aplica o princípio ao cenário e passa pela verificação anterior.',5),
('70000000-0000-4000-8000-000093100171','40000000-0000-4000-8000-000000930017','Dados: Pode localizar e corrigir certos erros de um bit.','Qual vantagem um código de correção de erro oferece além de um bit de paridade simples?',1),
